document.addEventListener("click",(function(t){var i=t.target.closest("[data-notifier-test-id]");if(i){var e=parseInt(i.dataset.notifierTestId,10),s=(i.dataset.notifierTestConfirm||"").replace(/\\n/g,"\n");confirm(s)&&Craft.postActionRequest("notifier/notifications/test",{notificationId:e},(function(t,i){"success"===i?t.success?Craft.cp.displaySuccess(t.message):Craft.cp.displayError(t.message||Craft.t("notifier","Test notification failed.")):Craft.cp.displayError(Craft.t("notifier","Test notification failed."))}))}}));